use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::{BTreeMap,BTreeSet}};
const ROOT:&str="/tmp/zopro-identical-control/corrected-run";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn add(p:impl AsRef<Path>,pins:&mut BTreeMap<String,String>){let p=p.as_ref();pins.insert(p.display().to_string(),hash(p));}
fn med(mut x:Vec<f64>)->f64{assert!(!x.is_empty());x.sort_by(f64::total_cmp);let n=x.len();if n%2==1{x[n/2]}else{(x[n/2-1]+x[n/2])/2.}}
fn gm(x:&[f64])->f64{assert!(!x.is_empty());(x.iter().map(|x|{assert!(*x>0.);x.ln()}).sum::<f64>()/x.len()as f64).exp()}
fn snapshot()->Value{let mut fields=BTreeMap::new();for p in ["/proc/loadavg","/proc/stat","/sys/fs/cgroup/cpu.stat","/sys/fs/cgroup/cpu.max","/sys/fs/cgroup/cpuset.cpus.effective","/sys/fs/cgroup/memory.events","/sys/fs/cgroup/memory.swap.events","/sys/devices/system/cpu/cpufreq/policy0/scaling_governor","/sys/devices/system/cpu/cpufreq/policy0/scaling_cur_freq","/sys/devices/system/cpu/cpufreq/policy0/scaling_min_freq","/sys/devices/system/cpu/cpufreq/policy0/scaling_max_freq"]{if let Ok(s)=fs::read_to_string(p){fields.insert(p,s);}}json!(fields)}
fn analyze(){let r=Path::new(ROOT);save(r.join("host-after.json"),&snapshot());let c=read(r.join("perf-plan.json"));assert_eq!(read(r.join("performance/result.json"))["status"],"complete");for(p,h)in c["pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}assert_eq!(c["variants"][0]["binary"],c["variants"][1]["binary"]);assert_eq!(c["variants"][0].get("environment"),None);assert_eq!(c["variants"][1].get("environment"),None);
 let data=read(r.join("performance/rows.json"));let rows=data.as_array().unwrap();assert_eq!(rows.len(),56);let mut sdk=0;let mut samples=0;let mut profiles=BTreeMap::new();let mut processes=Vec::new();for row in rows{let rounds=if row["phase"]=="latency"{31}else{51};assert_eq!(row["samples_ms"].as_array().unwrap().len(),rounds);assert_eq!(row["summary"]["rounds"],rounds);assert_eq!(row["summary"]["workers"],32);assert_eq!(row["summary"]["priming"],3);sdk+=rounds+3;
 let xs:Vec<f64>=row["samples_ms"].as_array().unwrap().iter().map(|x|x.as_f64().unwrap()).collect();let m=med(xs.clone());let first=med(xs[..5].to_vec());let last=med(xs[xs.len()-5..].to_vec());let cpu=(row["summary"]["user_cpu_ms"].as_f64().unwrap()+row["summary"]["system_cpu_ms"].as_f64().unwrap())/rounds as f64;let resource=|name:&str|row["summary"][name].as_f64().unwrap()/rounds as f64;
 processes.push(json!({"case":row["case"],"variant":row["variant"],"phase":row["phase"],"block":row["block"],"median_ms":m,"first5_ms":first,"last5_ms":last,"last_first_ratio":last/first,"min_ms":xs.iter().copied().fold(f64::INFINITY,f64::min),"max_ms":xs.iter().copied().fold(0.,f64::max),"MAD_ms":med(xs.iter().map(|x|(x-m).abs()).collect()),"CPU_ms_per_request":cpu,"minor_faults_per_request":resource("minor_faults"),"involuntary_switches_per_request":resource("involuntary_switches"),"voluntary_switches_per_request":resource("voluntary_switches"),"whole_process_RSS_mib":row["summary"]["whole_process_maxrss_kib"].as_f64().unwrap()/1024.}));
 if row["phase"]=="profile"{let p=&row["profile"];assert_eq!(p["lost_records"],0);assert_eq!(p["sampled_pids"].as_array().unwrap().len(),1);samples+=p["samples"].as_u64().unwrap();profiles.insert(row["variant"].as_str().unwrap().to_owned(),p.clone());}}
 assert_eq!(sdk,1944);let mut failures=Vec::new();let mut cases=BTreeMap::new();let mut all_ratios=Vec::new();for case in c["cases"].as_array().unwrap(){let name=case["name"].as_str().unwrap();let mut ratios=Vec::new();let mut engines=BTreeMap::new();for variant in ["a","b"]{let ps:Vec<_>=processes.iter().filter(|p|p["case"]==name&&p["variant"]==variant&&p["phase"]=="latency").collect();assert_eq!(ps.len(),3);engines.insert(variant,json!({"request_ms":med(ps.iter().map(|p|p["median_ms"].as_f64().unwrap()).collect()),"CPU_ms_per_request":med(ps.iter().map(|p|p["CPU_ms_per_request"].as_f64().unwrap()).collect()),"maximum_process_RSS_mib":ps.iter().map(|p|p["whole_process_RSS_mib"].as_f64().unwrap()).fold(0.,f64::max)}));}
 for block in 0..3{let ms=|v:&str|processes.iter().find(|p|p["case"]==name&&p["variant"]==v&&p["phase"]=="latency"&&p["block"]==block).unwrap()["median_ms"].as_f64().unwrap();let ratio=ms("b")/ms("a");ratios.push(ratio);if !(1./1.05..=1.05).contains(&ratio){failures.push(format!("{name}/b{block} b/a={ratio}"));}}let paired=med(ratios.clone());if !(1./1.03..=1.03).contains(&paired){failures.push(format!("{name} paired median b/a={paired}"));}all_ratios.extend(&ratios);let pooled:Vec<_>=processes.iter().filter(|p|p["case"]==name&&p["phase"]=="latency").map(|p|p["median_ms"].as_f64().unwrap()).collect();let baseline=med(pooled);let refs=if case["reference"].is_object(){json!({"supplied_CPU_ms":case["reference"]["cpu_ms"],"supplied_Metal_ms":case["reference"]["metal_ms"],"CPU_speedup":case["reference"]["cpu_ms"].as_f64().unwrap()/baseline,"Metal_speedup":case["reference"]["metal_ms"].as_f64().unwrap()/baseline})}else{Value::Null};cases.insert(name.to_owned(),json!({"labels":engines,"block_ratios":ratios,"paired_median_b_a":paired,"paired_geomean_b_a":gm(&ratios),"pooled_baseline_ms":baseline,"references":refs}));}
 let inv=read(r.join("performance/proof-inventory.json"));assert_eq!(inv.as_object().unwrap().len(),112);let mut inventory=BTreeMap::new();let mut ids:BTreeSet<String>=serde_json::from_value(c["prior_proof_sha256"].clone()).unwrap();for(p,h)in inv.as_object().unwrap(){let p=r.join("performance").join(p);assert_eq!(hash(&p),h.as_str().unwrap());if p.extension().is_some_and(|x|x=="proof"){assert_eq!(fs::metadata(&p).unwrap().len(),164);assert!(ids.insert(h.as_str().unwrap().into()));}inventory.insert(p.display().to_string(),h.as_str().unwrap().to_owned());}assert_eq!(ids.len(),5826);save(r.join("proof-inventory.json"),&json!(inventory));save(r.join("analysis.json"),&json!({"status":"complete identical-binary local control","sdk_requests":sdk,"distinct_gnark_exports":56,"proof_public_members":112,"profile_samples":samples,"profiles":profiles,"processes":processes,"cases":cases,"calibration_bound_crossings":failures,"all_bounds_pass":failures.is_empty(),"all_nine_block_ratio_geomean":gm(&all_ratios),"same_binary":c["variants"][0]["binary"],"same_binary_sha256":c["pins"][c["variants"][0]["binary"].as_str().unwrap()],"next_prior_proof_count":5826,"new_algorithm":false,"adopted":false,"goal_achieved":false}));println!("1944SDK56Gnark,{}samples;identicalbinary boundcrossings{}",samples,failures.len());}
fn main(){assert_eq!(std::env::args().nth(1).as_deref(),Some("analyze"));analyze();}
